Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int INF = 1000000009;
typedef pair<int,int> pii;
typedef pair<pii,int> ppi;

struct Edge {
    int u, v, flow, capacity;
    Edge(int u_, int v_, int f_, int c_) : u(u_), v(v_), flow(f_), capacity(c_) {}
};

vector<vector<int>> G;
vector<Edge> E;
vector<int> level, work;
int src, sink;

void addEdge(int u, int v, int c) {
    G[u].push_back((int)E.size());
    E.push_back(Edge(u, v, 0, c));
    G[v].push_back((int)E.size());
    E.push_back(Edge(v, u, 0, 0));
}

bool buildLevels() {
    fill(level.begin(), level.end(), -1);
    queue<int> Q;
    Q.push(src);
    level[src] = 0;
    while (!Q.empty()) {
        int u = Q.front(); Q.pop();
        for (int id : G[u]) {
            int v = E[id].v;
            if (level[v] == -1 && E[id].flow < E[id].capacity) {
                level[v] = level[u] + 1;
                Q.push(v);
                if (v == sink) return true;
            }
        }
    }
    return false;
}

long long dinic() {
    long long ans = 0;
    while (buildLevels()) {
        fill(work.begin(), work.end(), 0);

        function<long long(int,int)> augment;
        augment = [&](int u, int f) -> long long {
            if (f == 0) return 0;
            if (u == sink) return f;
            for (int &i = work[u]; i < (int)G[u].size(); ++i) {
                int id = G[u][i];
                int v = E[id].v;
                if (level[v] != level[u] + 1) continue;
                long long pushed = augment(v, min(f, E[id].capacity - E[id].flow));
                if (pushed) {
                    E[id].flow += (int)pushed;
                    E[id ^ 1].flow -= (int)pushed;
                    return pushed;
                }
            }
            return 0;
        };

        while (long long pushed = augment(src, INF)) ans += pushed;
    }
    return ans;
}

int n, m, deadline;
char sci[101][101], rea[101][101];
int danger[101][101];

bool valid(int r, int c) { return r >= 0 && c >= 0 && r < n && c < m; }
int idCell(int x, int y) { return 1 + m * x + y; }

int main() {
    ios::sync_with_stdio(false);
    cin >> n >> deadline;
    ++deadline;
    m = n;

    for (int i = 0; i < n; ++i) cin >> sci[i];

    queue<pii> q0;
    for (int i = 0; i < n; ++i) {
        cin >> rea[i];
        for (int j = 0; j < m; ++j) {
            danger[i][j] = INF;
            if (rea[i][j] == 'Z') {
                q0.push(pii(i, j));
                danger[i][j] = 1;
            }
        }
    }

    while (!q0.empty()) {
        int x = q0.front().first;
        int y = q0.front().second;
        q0.pop();
        for (int dx = -1; dx <= 1; ++dx)
            for (int dy = -1; dy <= 1; ++dy) {
                if (abs(dx) + abs(dy) != 1) continue;
                int nx = x + dx, ny = y + dy;
                if (valid(nx, ny) && danger[nx][ny] == INF && sci[nx][ny] != 'Y') {
                    danger[nx][ny] = danger[x][y] + 1;
                    q0.push(pii(nx, ny));
                }
            }
    }

    src = 0;
    sink = n * n + n * n + 1;
    int nodes = n * n * 2 + 2;
    G.assign(nodes, vector<int>());
    E.clear();
    level.assign(nodes, -1);
    work.assign(nodes, 0);

    for (int x = 0; x < n; ++x) {
        for (int y = 0; y < m; ++y) {
            if (sci[x][y] >= '1' && sci[x][y] <= '9')
                addEdge(src, idCell(x, y), sci[x][y] - '0');
            if (rea[x][y] >= '1' && rea[x][y] <= '9')
                addEdge(n * n + idCell(x, y), sink, rea[x][y] - '0');

            for (int X = 0; X < n; ++X) {
                for (int Y = 0; Y < m; ++Y) {
                    if (sci[x][y] == 'Y' || sci[x][y] == 'Z' || rea[X][Y] == 'Y' || rea[X][Y] == 'Z')
                        continue;

                    bool seen[101][101] = {};
                    queue<ppi> q1;
                    q1.push(ppi(pii(x, y), 1));
                    seen[x][y] = true;
                    while (!q1.empty()) {
                        int cx = q1.front().first.first;
                        int cy = q1.front().first.second;
                        int tim = q1.front().second;
                        q1.pop();
                        if (cx == X && cy == Y) {
                            seen[X][Y] = true;
                            break;
                        }
                        if (tim >= danger[cx][cy] || tim >= deadline) continue;
                        for (int dx = -1; dx <= 1; ++dx) {
                            for (int dy = -1; dy <= 1; ++dy) {
                                if (abs(dx) + abs(dy) != 1) continue;
                                int nx = cx + dx, ny = cy + dy;
                                if (valid(nx, ny) && !seen[nx][ny] &&
                                    sci[nx][ny] != 'Y' && sci[nx][ny] != 'Z' &&
                                    tim + 1 <= danger[nx][ny]) {
                                    seen[nx][ny] = true;
                                    q1.push(ppi(pii(nx, ny), tim + 1));
                                }
                            }
                        }
                    }
                    if (seen[X][Y])
                        addEdge(idCell(x, y), n * n + idCell(X, Y), INF);
                }
            }
        }
    }

    cout << dinic() << endl;
    return 0;
}
